def countSteppingNumbers(low: str, high: str):
    MOD = 10**9 + 7

    def solve(S):
        L = len(S)
        memo = {}

        def dp(pos, last_digit, is_less, is_started):
            state = (pos, last_digit, is_less, is_started)
            if state in memo:
                return memo[state]

            if pos == L:
                return 1 if is_started else 0

            res = 0
            limit = int(S[pos]) if not is_less else 9

            # Case where we haven't started placing non-zero digits yet.
            if not is_started:
                # Option A: Continue with leading zeros (representing numbers of fewer digits than L).
                # Because the problem states no leading zeros, and low/high are positive,
                # a number like "01" is treated as "1". 
                # If we place '0' at pos=0, it effectively means we're counting numbers with < L digits.
                # Since S[0] >= 1 (no leading zeros), placing '0' always makes the result less than S.
                res = (res + dp(pos + 1, -1, True, False)) % MOD

                # Option B: Start the number with a non-zero digit d from 1 to limit.
                for d in range(1, limit + 1):
                    new_is_less = is_less or (d < limit)
                    res = (res + dp(pos + 1, d, new_is_less, True)) % MOD
            else:
                # Case where we have already started placing digits.
                # The next digit must differ from the last digit by exactly 1.
                for d in [last_digit - 1, last_digit + 1]:
                    if 0 <= d <= limit:
                        new_is_less = is_less or (d < limit)
                        res = (res + dp(pos + 1, d, new_is_less, True)) % MOD

            memo[state] = res
            return res

        # The DP counts all stepping numbers in [1, int(S)].
        return dp(0, -1, False, False)

    def isStepping(s):
        if not s: return False
        for i in range(len(s) - 1):
            if abs(int(s[i]) - int(s[i+1])) != 1:
                return False
        return True

    # Standard inclusion-exclusion for ranges: Count(low, high) = Count(high) - Count(low).
    # Then we add 1 if 'low' itself is a stepping number because solve(low) excludes it.
    ans = (solve(high) - solve(low)) % MOD
    if isStepping(low):
        ans = (ans + 1) % MOD

    return ans

