import math

def canReachCorner(xCorner: int, yCorner: int, circles: list[list[int]]) -> bool:
    # A path from (0, 0) to (xCorner, yCorner) exists if and only if no connected component of
    # circles connects the "top-left" boundary {Left side OR Top side} to the
    # "bottom-right" boundary {Right side OR Bottom side}.
    # The corners (0, 0) and (xCorner, yCorner) are not part of these boundaries.

    def touches_side(xi, yi, ri, xC, yC, side):
        if side == 'L': # x = 0, y in (0, yC)
            if xi**2 >= ri**2: return False
            dy = math.sqrt(ri**2 - xi**2)
            # Does there exist y in (0, yC) such that |y - yi| <= dy?
            # This is true if the interval [yi - dy, yi + dy] overlaps with (0, yC).
            return max(0, yi - dy) < min(yC, yi + dy)
        elif side == 'R': # x = xC, y in (0, yC)
            dx = abs(xC - xi)
            if dx**2 >= ri**2: return False
            dy = math.sqrt(ri**2 - dx**2)
            return max(0, yi - dy) < min(yC, yi + dy)
        elif side == 'B': # y = 0, x in (0, xC)
            if yi**2 >= ri**2: return False
            dx = math.sqrt(ri**2 - yi**2)
            return max(0, xi - dx) < min(xC, xi + dx)
        elif side == 'T': # y = yC, x in (0, xC)
            dy_val = abs(yC - yi)
            if dy_val**2 >= ri**2: return False
            dx = math.sqrt(ri**2 - dy_val**2)
            return max(0, xi - dx) < min(xC, xi + dx)
        return False

    n = len(circles)
    # Determine which sides each circle touches
    touches = []
    for i in range(n):
        xi, yi, ri = circles[i]
        t_l = touches_side(xi, yi, ri, xCorner, yCorner, 'L')
        t_r = touches_side(xi, yi, ri, xCorner, yCorner, 'R')
        t_b = touches_side(xi, yi, ri, xCorner, yCorner, 'B')
        t_t = touches_side(xi, yi, ri, xCorner, yCorner, 'T')
        touches.append((t_l, t_r, t_b, t_t))

    # Build adjacency list for circles that intersect/touch each other
    adj = [[] for _ in range(n)]
    for i in range(n):
        xi, yi, ri = circles[i]
        for j in range(i + 1, n):
            xj, yj, rj = circles[j]
            dist_sq = (xi - xj)**2 + (yi - yj)**2
            if dist_sq <= (ri + rj)**2:
                adj[i].append(j)
                adj[j].append(i)

    # A component blocks the path if it connects {L or T} and {R or B}
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                component.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

            has_top_left = False
            has_bottom_right = False
            for idx in component:
                t_l, t_r, t_b, t_t = touches[idx]
                if t_l or t_t:
                    has_top_left = True
                if t_r or t_b:
                    has_bottom_right = True

            if has_top_left and has_bottom_right:
                return False

    return True

