from typing import List

def countOfPeaks(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    # Use a Fenwick Tree (Binary Indexed Tree) to store peak indicators.
    # bit[i] will help in calculating the prefix sum of peaks up to index i-1.
    bit = [0] * (n + 1)

    def update_bit(i: int, delta: int):
        idx = i + 1  # BIT is 1-indexed
        while idx <= n:
            bit[idx] += delta
            idx += idx & (-idx)

    def query_bit(i: int) -> int:
        s = 0
        idx = i + 1
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s

    # A peak is an element nums[k] such that 0 < k < n-1 and 
    # nums[k] > nums[k-1] and nums[k] > nums[k+1].
    def is_peak(k: int) -> bool:
        if 0 < k < n - 1:
            return nums[k] > nums[k-1] and nums[k] > nums[k+1]
        return False

    # Initialize the BIT with peaks from the original array.
    for i in range(1, n - 1):
        if is_peak(i):
            update_bit(i, 1)

    results = []
    for q in queries:
        type_q = q[0]
        if type_q == 1:
            l, r = q[1], q[2]
            # A peak in subarray nums[l..r] must be at an index k where l < k < r.
            # This is equivalent to summing the indicators for indices [l+1, r-1].
            if l + 1 <= r - 1:
                results.append(query_bit(r - 1) - query_bit(l))
            else:
                results.append(0)
        elif type_q == 2:
            idx, val = q[1], q[2]
            # Changing nums[idx] can only affect the peak status of indices idx-1, idx, and idx+1.
            # We check these three potential peaks before updating the value.
            for k in (idx - 1, idx, idx + 1):
                if is_peak(k):
                    update_bit(k, -1)

            nums[idx] = val

            # After updating the value, we re-check the same three indices.
            for k in (idx - 1, idx, idx + 1):
                if is_peak(k):
                    update_bit(k, 1)

    return results

