def minimumChanges(s: str, k: int):
    n = len(s)
    # costs[i][j] stores the minimum changes to make substring s[i:j] a semi-palindrome.
    # Substrings of length 1 cannot be semi-palindromes because 1 <= d < len has no solution.
    costs = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(i + 2, n + 1):
            L = j - i
            best_cost = float('inf')
            # A string of length L is a semi-palindrome if there exists d such that:
            # 1 <= d < L, L % d == 0, and for every r in [0, d), the indices congruent to r mod d form a palindrome.
            for d in range(1, L):
                if L % d == 0:
                    current_d_cost = 0
                    # For each group of characters separated by distance d, calculate changes needed for palindrome.
                    for r in range(d):
                        chars = s[i+r : j : d]
                        m_len = len(chars)
                        if m_len > 1:
                            for idx in range(m_len // 2):
                                if chars[idx] != chars[m_len - 1 - idx]:
                                    current_d_cost += 1
                    if current_d_cost < best_cost:
                        best_cost = current_d_cost
            costs[i][j] = best_cost

    # dp[i][j] is the minimum cost to partition s[:i] into exactly j semi-palindrome substrings.
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for j in range(1, k + 1):
        prev_row = dp[j-1]
        curr_row = dp[j]
        # Every semi-palindrome substring must have length at least 2.
        # Therefore, to have j substrings, we need at least 2*j characters.
        for i in range(2 * j, n + 1):
            best = float('inf')
            # p is the split point; s[p:i] is the last substring (length >= 2).
            # The previous j-1 substrings must have occupied at least 2*(j-1) characters.
            for p in range(2 * (j - 1), i - 1):
                if prev_row[p] != float('inf'):
                    res = prev_row[p] + costs[p][i]
                    if res < best:
                        best = res
            curr_row[i] = best

    return int(dp[n][k])
