def minimumChanges(s: str, k: int):
    n = len(s)
    inf = float('inf')
    # Precompute the minimum changes to make any substring s[i:j] a semi-palindrome.
    # A string is a semi-palindrome if there exists d (1 <= d < L, L%d == 0) 
    # such that for every remainder r in [0, d), characters at indices x where x % d == r form a palindrome.
    costs = [[inf] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            L = j - i
            min_sub_cost = inf
            # Check all possible divisors d of the substring length L.
            for d in range(1, L):
                if L % d == 0:
                    current_d_cost = 0
                    m = L // d  # Number of characters in each modulo group.
                    for start_idx in range(d):
                        # For a fixed remainder 'start_idx', the indices are i+start_idx, i+start_idx+d, ...
                        # These form a sequence of length m. We check if it's a palindrome.
                        for x in range(m // 2):
                            if s[i + start_idx + x * d] != s[i + start_idx + (m - 1 - x) * d]:
                                current_d_cost += 1
                    if current_d_cost < min_sub_cost:
                        min_sub_cost = current_d_cost
            costs[i][j] = min_sub_cost

    # dp[i][j] is the minimum changes to partition the prefix s[:j] into i semi-palindromes.
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        # Each substring must have length at least 2 to be a semi-palindrome.
        # Therefore, the end index j must be at least 2*i.
        for j in range(2 * i, n + 1):
            # Iterate through all possible split points p.
            # The previous part s[:p] must have been partitioned into i-1 substrings (minimum length 2*(i-1)).
            for p in range(2 * (i - 1), j - 1):
                if dp[i-1][p] != inf and costs[p][j] != inf:
                    new_cost = dp[i-1][p] + costs[p][j]
                    if new_cost < dp[i][j]:
                        dp[i][j] = new_cost

    return dp[k][n]

