def minimumChanges(s: str, k: int):
    """
    Calculates the minimum letter changes required to partition string s into k substrings,
    each of which must be a "semi-palindrome".
    A semi-palindrome of length L has a divisor d (1 <= d < L) such that 
    for each remainder r from 0 to d-1, the characters at indices i where i % d == r
    form a palindrome.
    """
    n = len(s)
    # cost[i][j] will store the minimum changes to make substring s[i:j] semi-palindrome.
    cost = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    # Precompute divisors d such that 1 <= d < L and L % d == 0.
    divs = [[] for _ in range(n + 1)]
    for length in range(2, n + 1):
        for d in range(1, length):
            if length % d == 0:
                divs[length].append(d)

    # Precompute the cost to make each substring s[i:j] a semi-palindrome.
    for i in range(n):
        for j in range(i + 2, n + 1):
            L = j - i
            min_c = float('inf')
            # A string is semi-palindrome if there exists AT LEAST one such divisor d.
            for d in divs[L]:
                current_c = 0
                m = L // d
                # For each remainder r, the sequence T_r must be a palindrome.
                # The elements of T_r are at s[i + r], s[i + r + d], ..., s[i + r + (m-1)*d].
                for r in range(d):
                    # Check if sequence T_r is a palindrome:
                    # Compare character at index p with the character at the opposite end of the sequence.
                    for p in range(m // 2):
                        if s[i + r + p * d] != s[i + r + (m - 1 - p) * d]:
                            current_c += 1
                # We want to minimize changes over all possible divisors d.
                if current_c < min_c:
                    min_c = current_c
            cost[i][j] = min_c

    # dp[i][j] represents the minimum changes to partition s[:i] into j semi-palindromes.
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for count in range(1, k + 1):
        # To have 'count' semi-palindromes each of length >= 2, we need at least 2*count characters.
        for i in range(2 * count, n + 1):
            # Try all possible split points p such that s[p:i] is the last substring.
            # The previous substrings (count - 1) must have occupied s[:p].
            # Therefore, s[0:p] must be partitionable into count-1 semi-palindromes.
            for p in range(2 * (count - 1), i - 1):
                if dp[p][count - 1] != float('inf') and cost[p][i] != float('inf'):
                    new_val = dp[p][count - 1] + cost[p][i]
                    if new_val < dp[i][count]:
                        dp[i][count] = new_val

    return int(dp[n][k])

